conceptCard.exampleCode:
class Character:
    def __init__(self, name, hp):
        self.name = name
        self.hp = hp

    def take_damage(self, amount):
        self.hp -= amount

hero = Character("용사", 100)
monster = Character("고블린", 50)

hero.take_damage(30)
print(hero.hp, monster.hp)   # 70 50 (서로 영향 없음)

